/**
 * Motifs for catalog modules in R03 Samhälle (0.27). Same geometry format as motifs.ts.
 */
import type { Motif, Part, Role } from './motifs';

const p = (d: string, r: Role, hue?: number): Part => ({ t: 'path', d, r, hue });
const c = (cx: number, cy: number, rad: number, r: Role, hue?: number): Part => ({ t: 'circle', cx, cy, rad, r, hue });
const q = (x: number, y: number, w: number, h: number, r: Role, rx = 1.5, hue?: number): Part => ({ t: 'rect', x, y, w, h, rx, r, hue });
const G = { green: 115, orange: 26, red: 6, yellow: 46, blue: 210, grey: 220, purple: 285 } as const;
const fig = (x: number, y: number, s: number, r: Role): Part[] => [c(x, y - 14 * s, 5 * s, r), p(`M${x - 7 * s} ${y + 12 * s} V${y - 2 * s} C${x - 7 * s} ${y - 7 * s} ${x + 7 * s} ${y - 7 * s} ${x + 7 * s} ${y - 2 * s} V${y + 12 * s} Z`, r)];
const crowd = (y: number, n: number, s: number, roles: Role[]): Part[] => Array.from({ length: n }, (_, i) => fig(8 + ((48 / (n - 1 || 1)) * i), y, s, roles[i % roles.length]!)).flat();
const bubble = (x: number, y: number, w: number, h: number, r: Role): Part => p(`M${x + 4} ${y} H${x + w - 4} Q${x + w} ${y} ${x + w} ${y + 4} V${y + h - 4} Q${x + w} ${y + h} ${x + w - 4} ${y + h} H${x + 14} L${x + 6} ${y + h + 7} V${y + h} H${x + 4} Q${x} ${y + h} ${x} ${y + h - 4} V${y + 4} Q${x} ${y} ${x + 4} ${y} Z`, r);
const star = (x: number, y: number, r: number, role: Role, hue?: number): Part => { const pts = Array.from({ length: 10 }, (_, i) => { const a = -Math.PI / 2 + (i * Math.PI) / 5; const rr = i % 2 ? r * 0.45 : r; return `${(x + Math.cos(a) * rr).toFixed(1)} ${(y + Math.sin(a) * rr).toFixed(1)}`; }); return p(`M${pts.join(' L')} Z`, role, hue); };
const doc = (x: number, y: number, w: number, h: number, lines = 3): Part[] => [q(x, y, w, h, 'light', 2), p(Array.from({ length: lines }, (_, i) => `M${x + 5} ${y + 8 + i * 7} H${x + w - (i === lines - 1 ? 12 : 5)}`).join(' '), 'line')];
/** Public building with pediment and columns. */
const hall = (x: number, y: number, w: number, h: number, r: Role = 'main'): Part[] => [p(`M${x} ${y + 10} L${x + w / 2} ${y} L${x + w} ${y + 10} Z`, r), q(x, y + h - 5, w, 5, r, 1), ...[0, 1, 2, 3].map((i) => q(x + 3 + i * ((w - 10) / 3), y + 12, 4, h - 18, 'light', 1))];
const gavel = (x: number, y: number): Part[] => [p(`M${x} ${y} L${x + 12} ${y - 12} L${x + 18} ${y - 6} L${x + 6} ${y + 6} Z`, 'main'), p(`M${x + 9} ${y - 3} L${x + 24} ${y + 12}`, 'line'), q(x - 6, y + 16, 22, 5, 'accent2', 2)];
const scales = (x: number, y: number, s = 1, tilt = 0): Part[] => [p(`M${x} ${y - 20 * s} V${y + 18 * s} M${x - 10 * s} ${y + 18 * s} H${x + 10 * s} M${x - 20 * s} ${y - 14 * s - tilt} L${x + 20 * s} ${y - 14 * s + tilt}`, 'line'), p(`M${x - 20 * s} ${y - 14 * s - tilt} L${x - 27 * s} ${y + 2 * s - tilt} H${x - 13 * s} Z`, 'light'), p(`M${x - 27 * s} ${y + 2 * s - tilt} Q${x - 20 * s} ${y + 9 * s - tilt} ${x - 13 * s} ${y + 2 * s - tilt} Z`, 'main'), p(`M${x + 20 * s} ${y - 14 * s + tilt} L${x + 13 * s} ${y + 2 * s + tilt} H${x + 27 * s} Z`, 'light'), p(`M${x + 13 * s} ${y + 2 * s + tilt} Q${x + 20 * s} ${y + 9 * s + tilt} ${x + 27 * s} ${y + 2 * s + tilt} Z`, 'accent')];
const ballot = (x: number, y: number): Part[] => [q(x, y + 10, 28, 22, 'main', 2), q(x + 6, y + 9, 16, 3, 'line', 1), q(x + 8, y - 6, 12, 15, 'light', 1), p(`M${x + 10} ${y + 1} L${x + 13} ${y + 4} L${x + 18} ${y - 2}`, 'line')];
const coin = (x: number, y: number, r: number, role: Role = 'main'): Part[] => [c(x, y, r, role, G.yellow), c(x, y, r * 0.65, 'line')];
const bars = (vals: number[], x = 8, w = 48, base = 54, role: Role = 'main'): Part[] => vals.map((v, i) => q(x + i * (w / vals.length) + 1, base - v, w / vals.length - 3, v, i === vals.length - 1 ? 'accent' : role, 1.5));
const globe = (x: number, y: number, r: number): Part[] => [c(x, y, r, 'main', G.blue), p(`M${x - r * 0.6} ${y - r * 0.3} C${x - r * 0.2} ${y - r * 0.6} ${x} ${y} ${x + r * 0.3} ${y - r * 0.2} C${x + r * 0.6} ${y - r * 0.4} ${x + r * 0.7} ${y + r * 0.2} ${x + r * 0.3} ${y + r * 0.4} C${x} ${y + r * 0.5} ${x - r * 0.4} ${y + r * 0.3} ${x - r * 0.6} ${y - r * 0.3} Z`, 'accent', G.green)];
const flag = (x: number, y: number, r: Role, hue?: number): Part[] => [p(`M${x} ${y} V${y + 30}`, 'line'), p(`M${x} ${y} H${x + 18} L${x + 14} ${y + 6} L${x + 18} ${y + 12} H${x} Z`, r, hue)];
const megaphone = (x: number, y: number): Part[] => [p(`M${x} ${y - 5} L${x + 20} ${y - 14} V${y + 14} L${x} ${y + 5} Z`, 'main'), q(x - 6, y - 5, 7, 10, 'accent', 2), p(`M${x + 5} ${y + 6} L${x + 8} ${y + 16}`, 'line'), p(`M${x + 25} ${y - 8} C${x + 29} ${y - 4} ${x + 29} ${y + 4} ${x + 25} ${y + 8}`, 'line')];
const paper = (x: number, y: number, w: number, h: number): Part[] => [q(x, y, w, h, 'light', 2), q(x + 4, y + 4, w - 8, 6, 'main', 1), q(x + 4, y + 13, (w - 10) / 2, 10, 'accent', 1), p(`M${x + 4 + (w - 10) / 2 + 3} ${y + 15} H${x + w - 4} M${x + 4 + (w - 10) / 2 + 3} ${y + 20} H${x + w - 4} M${x + 4} ${y + 28} H${x + w - 4} M${x + 4} ${y + 33} H${x + w - 8}`, 'line')];
const phone = (x: number, y: number): Part[] => [q(x, y, 24, 42, 'main', 5), q(x + 3, y + 5, 18, 30, 'light', 2), c(x + 12, y + 38, 1.6, 'light')];
const house = (x: number, y: number, w: number, r: Role): Part[] => [p(`M${x} ${y + w * 0.45} L${x + w / 2} ${y} L${x + w} ${y + w * 0.45} V${y + w * 1.1} H${x} Z`, r), q(x + w * 0.38, y + w * 0.7, w * 0.24, w * 0.4, 'light', 1)];
const check = (x: number, y: number, s = 1): Part => p(`M${x - 5 * s} ${y} L${x - 1 * s} ${y + 4 * s} L${x + 6 * s} ${y - 4 * s}`, 'line');
const heart0 = (x: number, y: number): Part => p(`M${x} ${y + 7} C${x - 10} ${y} ${x - 8} ${y - 8} ${x - 4} ${y - 8} C${x - 2} ${y - 8} ${x} ${y - 6} ${x} ${y - 4} C${x} ${y - 6} ${x + 2} ${y - 8} ${x + 4} ${y - 8} C${x + 8} ${y - 8} ${x + 10} ${y} ${x} ${y + 7} Z`, 'main', G.red);
const arrowR = (x1: number, x2: number, y: number): Part => p(`M${x1} ${y} H${x2} M${x2 - 4} ${y - 4} L${x2} ${y} L${x2 - 4} ${y + 4}`, 'line');

